export default function Card({ title, description, children, accent }) {
  return (
    <div className={`rounded-3xl border border-indigo-700 bg-gradient-to-br from-indigo-800/80 to-purple-800/80 p-6 shadow-2xl shadow-indigo-950/20 dark:border-blue-300 dark:bg-gradient-to-br dark:from-blue-100/80 dark:to-purple-100/80 ${accent || ''}`}>
      <div className="mb-4 flex items-center justify-between gap-4">
        <h3 className="text-lg font-semibold text-slate-100 dark:text-slate-900">{title}</h3>
      </div>
      <p className="mb-6 text-sm leading-6 text-slate-400">{description}</p>
      {children}
    </div>
  );
}
